import{_ as t,l as r,o as e,c as n,v as i,p as s,x as l,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"内联启发","description":"","frontmatter":{"title":"内联启发","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/inlining-heuristics.md","filePath":"cs/inlining-heuristics.md","lastUpdated":1789023840000}'),h={name:"cs/inlining-heuristics.md"};function _(u,a,m,f,T,B){const o=r("Mermaid");return e(),n("div",null,[a[1]||(a[1]=i('<h1 id="内联启发" tabindex="-1">内联启发 <a class="header-anchor" href="#内联启发" aria-label="Permalink to &quot;内联启发&quot;">​</a></h1><div class="epigraph"><p>内联用调用点的体替换 `call`，消除开销并暴露过程内优化。预算、热度与是否递归决定做不做，而不是「凡是能内联都做」。</p><footer>—— 据 Davidson and Holler；Ayres 等内联研究；Appel；龙书过程间优化整理</footer></div><p>上一课<a href="/cs/interprocedural-callgraph">调用图</a>知道 callee。缺口是<strong>复制体的决策</strong>：小函数几乎总内联；大函数只在热路径；递归要阈值。本课钉启发与副作用（代码膨胀、编译时间），不写尾调用——下一课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>每次调用有 ABI 开销与屏障（许多优化不跨 <code>call</code>）。内联后常量实参触发 SCCP，虚调用可能去虚。代价：I-cache、编译时间、调试。缺口是<strong>成本模型</strong>，不是 CG 构造。</p><p>始终内联：<code>always_inline</code>、模板单态化后的小函数。永不：函数指针外部、<code>noinline</code>、过大。</p><h3 id="内联不是宏" tabindex="-1">内联不是宏 <a class="header-anchor" href="#内联不是宏" aria-label="Permalink to &quot;内联不是宏&quot;">​</a></h3><p>宏是记号改写，无作用域；内联是 IR 级，遵守作用域与类型。C 的 <code>inline</code> 关键字还与链接（弱符号）纠缠，后课符号。</p><p><span class="marginnote">经典编译器内联启发式。LLVM InlineCost。PGO 后课提供热度。本课静态：体大小、调用深度、是否有 alloca。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>自底向上沿 CG（先叶）。对每个调用点打分：指令数、是否可常量传播、是否在循环。超过预算停。递归：允许浅层或只内联一次（peel）。</p>',11)),(e(),s(p,null,{default:l(()=>[c(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20CG%5B%22%E8%B0%83%E7%94%A8%E5%9B%BE%22%5D%20--%3E%20COST%5B%22%E4%BB%A3%E4%BB%B7%20%2F%20%E6%94%B6%E7%9B%8A%22%5D%0A%20%20COST%20--%3E%20IN%5B%22%E5%A4%8D%E5%88%B6%E4%BD%93%22%5D%0A%20%20IN%20--%3E%20OPT%5B%22SCCP%20%2F%20DCE%20%2F%20LICM%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=i('<p>与单态化：特化后的体更小更值得内联。与栈：内联加深帧，除非再缩。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>间接调用：先去虚（唯一目标）再内联。失败则留 <code>call</code>。不要内联改变可观察异常表顺序的语言细节而不更新表。</p><p>链接期内联（LTO）看见其它 TU 的体——后课 LTO。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写完整 profile 计数。后课默认：内联由预算与热度约束。下一课尾调用：不内联也能把调用变成跳转。</p><p>也不把内联当混淆（故意复制）。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>内联消除调用并暴露优化；膨胀是代价。</li><li>启发：大小、热度、递归深度。</li><li>与摘要分析互补：不内联也能传 mod/ref。</li><li>出处：Davidson/Holler；Appel；龙书；对照 LLVM InlineCost。</li></ul>',9))])}const E=t(h,[["render",_]]);export{A as __pageData,E as default};
